function beginCourseVisit(id){if(!id||courseVisitOpen)return;learning.visits??={};learning.visits[id]??={entries:0,exits:0};learning.visits[id].entries++;learning.visits[id].lastEnteredAt=new Date().toISOString();courseVisitOpen=true;persistAccountState("learning",learning)}
