      const frame=document.createElement("iframe");frame.title="معاينة HTML معزولة";frame.setAttribute("sandbox","");frame.style.cssText="width:100%;height:270px;border:1px solid #dfe8df;border-radius:8px;background:white";frame.srcdoc=src;output.append(frame);document.querySelector("#runtime").textContent="معاينة HTML معزولة";return;
