      if(["python","html","css","javascript","sql"].includes(lang)&&activeCourseId===lang){const resultReady=(lang==="html"||lang==="css")?!!output.querySelector("iframe"):!!output.textContent.trim();practicePassed=!lastRunFailed&&source.trim()!==starter[lang].trim()&&resultReady;document.querySelector("#practice-status").textContent=practicePassed?"تم تشغيل تعديلك بنجاح. ارجع للدرس لإكماله.":"عدّل المثال بما يناسب التدريب، ثم شغّله بنجاح."}return;
