      document.querySelector("#runtime").textContent="SQLite مؤقت ومعزول";output.textContent="جارٍ تشغيل SQL…";const result=await authRequest("/api/run/sql",{code:source});const rendered=result.result.map(x=>x.kind==="rows"?x.rows.map(row=>Object.entries(row).map(([k,v])=>k+": "+String(v)).join("  |  ")).join("\n")||"لا توجد صفوف.":"تم تعديل "+x.changes+" صف.").join("\n\n");output.textContent=rendered;return;
