function armReminder(){clearTimeout(reminderTimer);const status=document.querySelector("#reminder-status"),card=document.querySelector("#reminder-card-title"),toggle=document.querySelector("#reminder-toggle");if(toggle)toggle.checked=remindersEnabled;if(!remindersEnabled){if(status)status.textContent="متوقفة";if(card)card.textContent="تنبيهات المتصفح متوقفة";return}if(!("Notification"in window)||Notification.permission!=="granted"){remindersEnabled=false;if(status)status.textContent="تتطلب إذن المتصفح";return}if(!schedule.time||!schedule.days?.length){if(status)status.textContent="اختر موعدًا أولًا";if(card)card.textContent="احفظ الأيام والوقت لتفعيل التنبيه";return}if(status)status.textContent="مفعّلة على هذا الجهاز";if(card)card.textContent="تنبيه المتصفح مفعّل";const now=new Date();let next=null;for(let ahead=0;ahead<8;ahead++){const candidate=new Date(now);candidate.setDate(now.getDate()+ahead);if(schedule.days.includes(candidate.getDay())){const [hour,minute]=schedule.time.split(":").map(Number);candidate.setHours(hour,minute,0,0);if(candidate>now){next=candidate;break}}}if(next){reminderTimer=setTimeout(()=>{const notification=new Notification("حان وقت جلسة مِداد",{body:"خذ خطوة اليوم في مسارك التعليمي.",tag:"midad-study"});notification.onclick=()=>window.focus();armReminder()},next-now)}}
async function turnOnReminders(){if(!("Notification"in window)){toast("هذا المتصفح لا يدعم تنبيهات الويب.");return}let permission=Notification.permission;if(permission!=="granted"){try{permission=await Notification.requestPermission()}catch{permission="denied"}}if(permission!=="granted"){remindersEnabled=false;toast("لم تُمنح صلاحية التنبيهات.");armReminder();return}remindersEnabled=true;schedule.remindersEnabled=true;persistAccountState("schedule",schedule);armReminder();toast("فُعّلت تنبيهات المتصفح. تعمل عند بقاء الموقع مفتوحًا.")}
document.querySelector("#enable-reminders").addEventListener("click",turnOnReminders);document.querySelector("#reminder-toggle").addEventListener("change",e=>{if(e.target.checked)turnOnReminders();else{remindersEnabled=false;schedule.remindersEnabled=false;persistAccountState("schedule",schedule);armReminder()}});
document.querySelector("#goal-hours").value=schedule.hours||"";document.querySelector("#reminder-time").value=schedule.time||"";document.querySelector("#save-schedule").addEventListener("click",()=>{const hours=document.querySelector("#goal-hours").value,time=document.querySelector("#reminder-time").value,days=[...document.querySelectorAll("#study-days input:checked")].map(x=>Number(x.value));if(!hours||!time||!days.length){toast("أدخل مدة ووقتًا واختر يومًا واحدًا على الأقل.");return}schedule={hours,time,days,remindersEnabled};persistAccountState("schedule",schedule);renderSchedule();toast(authenticatedEmail?"حُفظ جدولك في حسابك.":"أُضيف الجدول لهذه الجلسة فقط. أنشئ حسابًا لحفظه.")});document.querySelector("#edit-schedule").addEventListener("click",()=>{showPage("schedule");document.querySelector("#goal-hours").focus()});renderSchedule();
