const authForm=document.querySelector("#signin-form"),emailInput=document.querySelector("#auth-email"),codeInput=document.querySelector("#auth-code"),authFeedback=document.querySelector("#auth-feedback"),authSubmit=document.querySelector("#auth-submit");let authStep="email";authSubmit.addEventListener("click",()=>{if(!emailInput.value.trim()){authFeedback.textContent="اكتب بريدك الإلكتروني أولًا.";emailInput.focus();return}authForm.dispatchEvent(new Event("submit",{bubbles:true,cancelable:true}))});emailInput.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();authSubmit.click()}});codeInput.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();authSubmit.click()}});
async function authRequest(url,payload){let response;try{response=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify(payload)})}catch{throw new Error("تعذر الاتصال بخادم مِداد. افتح رابط الموقع الحالي أو أعد تشغيل الخادم.")}const data=await response.json().catch(()=>({error:"الخادم أعاد استجابة غير مفهومة."}));if(!response.ok)throw new Error(data.error||"تعذّر إكمال الطلب.");return data}
async function syncAccountState(){if(!authenticatedEmail)return;try{const response=await fetch("/api/state",{credentials:"same-origin"});if(!response.ok)return;const {state}=await response.json();if(state.profile){document.querySelector(".profile b").textContent=state.profile.firstName||authenticatedEmail;document.querySelector(".profile small").textContent=state.profile.education==="university"?"طالب جامعي":state.profile.education==="school"?"طالب مدرسة":state.profile.education==="professional"?"مجال التقنية":state.profile.education==="hobbyist"?"هاوي برمجة":"متعلم مِداد"}if(state.metrics)metrics=state.metrics;else await persistAccountState("metrics",metrics);if(state.schedule)schedule=state.schedule;else await persistAccountState("schedule",schedule);if(state.learning){learning={...learning,...state.learning,visits:state.learning.visits||{},levels:state.learning.levels||{}};activeCourseId=learning.selectedCourse||null;lessonIndex=activeCourseId?Number(learning.progress?.[activeCourseId]||0):0;if(activeCourseId){const course=courseInfo(activeCourseId);document.querySelector("#course-language").value=activeCourseId;language.value=course.editor;language.dispatchEvent(new Event("change"))}}else await persistAccountState("learning",learning);if(state.code){codeDrafts=state.code;if(codeDrafts[language.value])code.value=codeDrafts[language.value]}else await persistAccountState("code",codeDrafts);remindersEnabled=!!schedule.remindersEnabled;renderLesson();renderMetrics();renderSchedule();renderLines();document.querySelector(".editor-footer span").textContent="مساحة العمل محفوظة في حسابك"}catch{}}

authForm.addEventListener("submit",async e=>{e.preventDefault();authFeedback.textContent="";authSubmit.disabled=true;authSubmit.textContent="جارٍ المعالجة…";try{if(authStep==="email"){const email=emailInput.value.trim();if(!email||emailInput.validity.typeMismatch)throw new Error("أدخل بريدًا إلكترونيًا صحيحًا.");const result=await authRequest("/api/auth/request-code",{email});authStep="code";document.querySelector("#code-label").hidden=false;document.querySelector("#resend-code").hidden=false;emailInput.readOnly=true;document.querySelector("#auth-subtitle").textContent="أدخل رمز التحقق الذي أرسلناه إلى "+email;authFeedback.textContent=result.message;codeInput.required=true;codeInput.focus();authSubmit.textContent="تأكيد الرمز والدخول"}else{const email=emailInput.value.trim(),result=await authRequest("/api/auth/verify-code",{email,code:codeInput.value});authFeedback.textContent="تم تسجيل الدخول بنجاح.";authenticatedEmail=result.email;await syncAccountState();document.querySelector("#logout").hidden=false;document.querySelector(".account-label").textContent=result.email;document.querySelector(".account-label").dataset.page="home";document.querySelector(".profile b").textContent=result.email;document.querySelector(".profile small").textContent="حساب مِداد";document.querySelector("#auth-subtitle").textContent="حيّاك الله، حسابك جاهز.";authSubmit.textContent="تم تسجيل الدخول";if(result.onboardingRequired)document.querySelector("#onboarding-dialog").showModal();await loadFeatures();toast("تم تسجيل الدخول إلى مِداد.")}}catch(error){authFeedback.textContent=error.message;authSubmit.textContent=authStep==="email"?"إرسال رمز التحقق":"تأكيد الرمز والدخول"}finally{authSubmit.disabled=false}});
document.querySelector("#resend-code").addEventListener("click",async()=>{authFeedback.textContent="جارٍ إرسال رمز جديد…";try{const result=await authRequest("/api/auth/request-code",{email:emailInput.value.trim()});authFeedback.textContent=result.message}catch(error){authFeedback.textContent=error.message}});
document.querySelector("#onboarding-form").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form).entries()),feedback=document.querySelector("#onboarding-feedback"),button=form.querySelector("button[type=submit]");feedback.textContent="";button.disabled=true;button.textContent="جارٍ حفظ ملفك…";try{const response=await fetch("/api/state",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:"profile",value:data})});const result=await response.json();if(!response.ok)throw new Error(result.error||"تعذر حفظ بياناتك.");document.querySelector("#onboarding-dialog").close();document.querySelector(".profile b").textContent=data.firstName;document.querySelector(".profile small").textContent=data.education==="university"?"طالب جامعي":data.education==="school"?"طالب مدرسة":data.education==="professional"?"مجال التقنية":data.education==="hobbyist"?"هاوي برمجة":"متعلم مِداد";toast("حُفظ ملفك، وسيستخدم سَنَد هذه المعلومات لمساعدتك.")}catch(error){feedback.textContent=error.message;button.disabled=false;button.textContent="حفظ ومتابعة التعلّم"}});
